//
// Handlers for posts.routes.js. Contract: backend/API.md, "posts module
// (Phase 7)". Block N-B part 1: the reading endpoints. Part 2: posting,
// deleting and reacting.
//
// The database decides who may see what. Every handler calls one of the SQL
// functions of migration community_posts and passes its answer through. Never
// re-check scope, campus, country or demo-world rules here (backend/CLAUDE.md).
// The viewer is always req.user.id, set by requireAuth, never a query parameter.
//
// ⚠ Never log post text or photos.
import { randomUUID } from 'node:crypto';
import { supabase } from '../../config/supabase.js';
import { sendError, mapDbError } from '../../utils/respond.js';
import {
  parsePageLimit,
  readCursorParam,
  isUuid,
  encodeCursor,
  decodeCursor,
} from '../../utils/pagination.js';
import { checkContent, isReadablePhoto } from '../../utils/moderation.js';
import { isSingleEmoji } from '../../utils/emoji.js';

const COUNTRY_CODE_RE = /^[A-Z]{2}$/;
const SORTS = ['hot', 'new'];
const SCOPES = ['campus', 'country', 'global'];
const POST_MAX_LENGTH = 1000; // code points (runbook §1.12)
const POSTS_BUCKET = 'posts';

const regionNames = new Intl.DisplayNames(['en'], { type: 'region' });

/** The SQL functions return hot_score for building cursors; it never leaves the server. */
const toPostItem = ({ hot_score, ...item }) => item;

/**
 * `{ items, next_cursor }`, the envelope sendPage produces, built here because
 * the cursor is compound (value|id), as getChatHistory does. next_cursor comes
 * from the LAST row when the page is full, otherwise null. `sortField` is
 * 'created_at' or 'hot_score'; it is read before hot_score is removed.
 */
function buildPage(rows, limit, sortField) {
  const list = rows ?? [];
  const last = list[list.length - 1];
  return {
    items: list.map(toPostItem),
    next_cursor: list.length === limit ? encodeCursor(last[sortField], last.id) : null,
  };
}

/**
 * Reads `?sort` (hot by default) and `?cursor` for the country and Global
 * feeds. Returns null when either is invalid — the caller answers 400.
 */
function readSortedPageParams(query) {
  const sort = query.sort === undefined ? 'hot' : query.sort;
  if (!SORTS.includes(sort)) return null;

  const raw = readCursorParam(query.cursor);
  const cursor = raw === null ? null : decodeCursor(raw, sort === 'hot' ? 'number' : 'timestamp');
  if (raw !== null && cursor === null) return null;

  return {
    sort,
    limit: parsePageLimit(query.limit),
    sortField: sort === 'hot' ? 'hot_score' : 'created_at',
    // The SQL functions take the cursor as separate typed arguments.
    cursorArgs: {
      p_cursor_score: sort === 'hot' && cursor ? cursor.value : null,
      p_cursor_time: sort === 'new' && cursor ? cursor.value : null,
      p_cursor_id: cursor ? cursor.id : null,
    },
  };
}

/** `?limit` and a 'timestamp' cursor, for the lists that are always by time. Null → 400. */
function readTimePageParams(query) {
  const raw = readCursorParam(query.cursor);
  const cursor = raw === null ? null : decodeCursor(raw, 'timestamp');
  if (raw !== null && cursor === null) return null;

  return {
    limit: parsePageLimit(query.limit),
    cursorArgs: {
      p_cursor_time: cursor ? cursor.value : null,
      p_cursor_id: cursor ? cursor.id : null,
    },
  };
}

// ───────────────────────────────────────────────────────────────────────────
// GET /api/posts/countries
// ───────────────────────────────────────────────────────────────────────────
export const getCountries = async (req, res) => {
  try {
    const { data, error } = await supabase.rpc('countries_for_viewer', {
      p_viewer: req.user.id,
    });
    if (error) return mapDbError(res, error);

    const items = (data ?? [])
      .map(({ country_code, is_mine }) => ({
        code: country_code,
        name: regionNames.of(country_code) ?? country_code,
        is_mine: Boolean(is_mine),
      }))
      // Your own country first, then by name.
      .sort((a, b) => Number(b.is_mine) - Number(a.is_mine) || a.name.localeCompare(b.name, 'en'));

    return res.json({ items, next_cursor: null });
  } catch (error) {
    return mapDbError(res, error);
  }
};

// ───────────────────────────────────────────────────────────────────────────
// GET /api/posts/feed/campus — always newest first
// ───────────────────────────────────────────────────────────────────────────
export const getCampusFeed = async (req, res) => {
  try {
    const page = readTimePageParams(req.query);
    if (!page) return sendError(res, 400, 'INVALID_FORMAT');

    const { data, error } = await supabase.rpc('get_campus_feed', {
      p_viewer: req.user.id,
      p_limit: page.limit,
      ...page.cursorArgs,
    });
    if (error) return mapDbError(res, error);

    return res.json(buildPage(data, page.limit, 'created_at'));
  } catch (error) {
    return mapDbError(res, error);
  }
};

// ───────────────────────────────────────────────────────────────────────────
// GET /api/posts/feed/country/:code — hot (default) or new, plus can_post
// ───────────────────────────────────────────────────────────────────────────
export const getCountryFeed = async (req, res) => {
  try {
    const code = String(req.params.code ?? '').toUpperCase();
    if (!COUNTRY_CODE_RE.test(code)) return sendError(res, 400, 'INVALID_FORMAT');

    const page = readSortedPageParams(req.query);
    if (!page) return sendError(res, 400, 'INVALID_FORMAT');

    const [feed, canPost] = await Promise.all([
      supabase.rpc('get_country_feed', {
        p_viewer: req.user.id,
        p_country: code,
        p_sort: page.sort,
        p_limit: page.limit,
        ...page.cursorArgs,
      }),
      supabase.rpc('can_post_in_feed', {
        p_viewer: req.user.id,
        p_scope: 'country',
        p_country: code,
      }),
    ]);
    if (feed.error) return mapDbError(res, feed.error);
    if (canPost.error) return mapDbError(res, canPost.error);

    return res.json({
      ...buildPage(feed.data, page.limit, page.sortField),
      can_post: canPost.data === true,
    });
  } catch (error) {
    return mapDbError(res, error);
  }
};

