// ═══════════════════════════════════════════════════════════════════════════
// Block N-B part 2 — posting, deleting and reacting.
// ═══════════════════════════════════════════════════════════════════════════

// 🔒 FILE NAMES (6B's rule). Photo URLs are public, so a stored name is a random
// uuid and nothing else: never a user id. The extension comes from the mimetype,
// which multer has already limited to these three, and isReadablePhoto confirms.
const PHOTO_EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };

const HTTPS_URL_RE = /^https:\/\/\S+$/i;
const isHttpsUrl = (value) => typeof value === 'string' && HTTPS_URL_RE.test(value);
const isPositiveInt = (value) => Number.isInteger(value) && value > 0;

/**
 * The GIF rule V-C uses for messages: provider 'klipy', a string id, an https
 * url, an optional https preview_url, positive integer width and height. Keeps
 * only those keys. Returns null for anything else (→ 400 INVALID_GIF).
 */
function parseGif(raw) {
  let gif;
  try {
    gif = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch {
    return null;
  }
  if (!gif || typeof gif !== 'object' || Array.isArray(gif)) return null;

  const { provider, id, url, preview_url, width, height } = gif;
  if (provider !== 'klipy') return null;
  if (typeof id !== 'string' || id.length === 0) return null;
  if (!isHttpsUrl(url)) return null;
  if (preview_url !== undefined && preview_url !== null && !isHttpsUrl(preview_url)) return null;
  if (!isPositiveInt(width) || !isPositiveInt(height)) return null;

  return { provider, id, url, ...(preview_url ? { preview_url } : {}), width, height };
}

/**
 * What each checkContent outcome saves (API.md, POST /api/posts). Nothing
 * becomes public unchecked: `checked: false` is held, whatever the outcome
 * says, and leaves moderation_checked_at empty so the re-check job finds it.
 */
function moderationFields(result) {
  const checkedAt = result.checked ? new Date().toISOString() : null;

  if (result.outcome === 'hold' || !result.checked) {
    return {
      moderation_status: 'pending',
      moderation_scores: result.scores,
      moderation_checked_at: checkedAt,
      moderation_support: result.support === true,
    };
  }

  return {
    moderation_status: 'active',
    moderation_scores: result.scores,
    moderation_checked_at: checkedAt,
    // A nudge only gets here with confirm=true ("Post anyway").
    moderation_flagged: result.outcome === 'nudge',
  };
}

/** Best effort: a file left behind costs storage, never correctness. Logs no names. */
async function removePhotos(paths) {
  if (paths.length === 0) return;
  const { error } = await supabase.storage.from(POSTS_BUCKET).remove(paths);
  if (error) console.error('[posts] could not remove', paths.length, 'uploaded photo(s)');
}

// ───────────────────────────────────────────────────────────────────────────
// POST /api/posts — multipart; multer (posts.routes.js) has already checked
// the photo count, sizes and declared types.
//
// ⛔ THE ORDER MATTERS (runbook §1.10): check everything, moderate, and only
// then upload; insert; if the insert fails, delete the uploads first.
// ───────────────────────────────────────────────────────────────────────────
export const createPost = async (req, res) => {
  let uploaded = []; // storage paths, removed again if anything below fails
  try {
    const files = req.files ?? [];
    const body = req.body ?? {};

    // b. Fields.
    if (body.content !== undefined && typeof body.content !== 'string') {
      return sendError(res, 400, 'INVALID_FORMAT');
    }
    const content = (body.content ?? '').trim();

    const parentPostId = body.parent_post_id === undefined || body.parent_post_id === ''
      ? null
      : body.parent_post_id;
    if (parentPostId !== null && !isUuid(parentPostId)) return sendError(res, 400, 'INVALID_FORMAT');
    const isReply = parentPostId !== null;

    // Ignored for replies: the trigger copies the parent's scope.
    const scope = body.scope === undefined || body.scope === '' ? 'campus' : body.scope;
    if (!isReply && !SCOPES.includes(scope)) return sendError(res, 400, 'INVALID_FORMAT');

    let gif = null;
    if (body.gif !== undefined && body.gif !== '') {
      gif = parseGif(body.gif);
      if (!gif) return sendError(res, 400, 'INVALID_GIF');
    }

    const confirm = body.confirm === 'true';

    // c. Rules, in this order.
    if ([...content].length > POST_MAX_LENGTH) {
      return sendError(res, 400, 'CONTENT_TOO_LONG', { max: POST_MAX_LENGTH });
    }
    if (!content && files.length === 0 && !gif) return sendError(res, 400, 'EMPTY_POST');
    if (files.length > 0 && (gif || isReply)) return sendError(res, 400, 'MEDIA_CONFLICT');

    // The declared mimetype proves nothing, and a photo that can't be read
    // would block the re-check job forever.
    const readable = await Promise.all(files.map((file) => isReadablePhoto(file)));
    if (readable.includes(false)) return sendError(res, 400, 'INVALID_FILE_TYPE');

    // d. Moderation, before anything is stored. Never throws.
    const result = await checkContent({ text: content, images: files });
    if (result.outcome === 'nudge' && !confirm) {
      // Nothing saved, nothing uploaded.
      return res.status(422).json({ error: 'MODERATION_NUDGE', categories: result.categories });
    }
    const moderation = moderationFields(result);
    const held = moderation.moderation_status === 'pending';

    // e. Only now upload, with random names.
    const imageUrls = [];
    for (const file of files) {
      const path = `${randomUUID()}.${PHOTO_EXT[file.mimetype] ?? 'jpg'}`;
      const { error: uploadError } = await supabase.storage
        .from(POSTS_BUCKET)
        .upload(path, file.buffer, { contentType: file.mimetype, upsert: false });
      if (uploadError) throw uploadError;
      uploaded.push(path);
      imageUrls.push(supabase.storage.from(POSTS_BUCKET).getPublicUrl(path).data.publicUrl);
    }

    // f. Insert. The BEFORE INSERT trigger fills university_id, country_code
    // and is_demo, and enforces the reply rules and the rate limits.
    const { data: inserted, error: insertError } = await supabase
      .from('posts')
      .insert({
        author_id: req.user.id,
        ...(isReply ? { parent_post_id: parentPostId } : { scope }),
        content,
        image_urls: imageUrls,
        gif,
        ...moderation,
      })
      .select('id')
      .single();

    if (insertError) {
      await removePhotos(uploaded);
      uploaded = [];
      // Only code and message: a check violation's `details` holds the failing
      // row, post text included, and mapDbError logs what it can't map.
      return mapDbError(res, { code: insertError.code, message: insertError.message });
    }
    uploaded = []; // the row points at them now

    // g. Read it back as the author sees it.
    const { data: rows, error: readError } = await supabase.rpc('get_post_item', {
      p_viewer: req.user.id,
      p_post_id: inserted.id,
    });
    if (readError) return mapDbError(res, readError);
    const row = rows?.[0];
    if (!row) return sendError(res, 500, 'INTERNAL_ERROR');

    const post = toPostItem(row);
    if (held) {
      return res.status(202).json({ post, held: true, support: result.checked && result.support === true });
    }
    return res.status(201).json({ post });
  } catch (error) {
    await removePhotos(uploaded);
    return mapDbError(res, { code: error?.code, message: error?.message });
  }
};

// ───────────────────────────────────────────────────────────────────────────
// DELETE /api/posts/:id — the author only; sets deleted_at, keeps the photos
// (a daily backend job removes them and the row after 90 days, §1.8).
// ───────────────────────────────────────────────────────────────────────────
export const deletePost = async (req, res) => {
  try {
    const postId = req.params.id;
    if (!isUuid(postId)) return sendError(res, 400, 'INVALID_FORMAT');

    const { data: post, error } = await supabase
      .from('posts')
      .select('author_id, deleted_at')
      .eq('id', postId)
      .maybeSingle();
    if (error) return mapDbError(res, error);
    if (!post) return sendError(res, 404, 'POST_NOT_FOUND');

    // The service-role client bypasses RLS: this comparison IS the ownership check.
    if (post.author_id !== req.user.id) return sendError(res, 403, 'FORBIDDEN');

    // Deleting twice is fine: the first time stands.
    if (!post.deleted_at) {
      const { error: updateError } = await supabase
        .from('posts')
        .update({ deleted_at: new Date().toISOString() })
        .eq('id', postId)
        .eq('author_id', req.user.id)
        .is('deleted_at', null);
      if (updateError) return mapDbError(res, updateError);
    }

    return res.json({ id: postId, deleted: true });
  } catch (error) {
    return mapDbError(res, error);
  }
};

/** react_to_post with an emoji, or null to remove the caller's reaction. */
async function respondWithReaction(req, res, emoji) {
  const postId = req.params.id;
  const { data, error } = await supabase.rpc('react_to_post', {
    p_post_id: postId,
    p_user_id: req.user.id,
    p_emoji: emoji,
  });
  if (error) return mapDbError(res, error);

  const row = data?.[0];
  if (!row) return sendError(res, 404, 'POST_NOT_FOUND');

  return res.json({
    post_id: postId,
    viewer_reaction: row.viewer_reaction ?? null,
    reactions_total: row.reactions_total,
    reaction_counts: row.reaction_counts,
  });
}

// ───────────────────────────────────────────────────────────────────────────
// PUT /api/posts/:id/reaction — body { emoji }; one reaction per person
// ───────────────────────────────────────────────────────────────────────────
export const setReaction = async (req, res) => {
  try {
    if (!isUuid(req.params.id)) return sendError(res, 400, 'INVALID_FORMAT');
    const emoji = req.body?.emoji;
    if (!isSingleEmoji(emoji)) return sendError(res, 400, 'INVALID_EMOJI');

    return await respondWithReaction(req, res, emoji);
  } catch (error) {
    return mapDbError(res, error);
  }
};

// ───────────────────────────────────────────────────────────────────────────
// DELETE /api/posts/:id/reaction
// ───────────────────────────────────────────────────────────────────────────
export const removeReaction = async (req, res) => {
  try {
    if (!isUuid(req.params.id)) return sendError(res, 400, 'INVALID_FORMAT');

    return await respondWithReaction(req, res, null);
  } catch (error) {
    return mapDbError(res, error);
  }
};
